import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles a sheet's settings assign to user names. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, SheetRepository sheetStore, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The role of a user name on the sheet: the one assigned, else clerk. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** Assign a role (clerk or steward) to a user name, replacing the one it had. The sheet is locked
     *  first, so two assignments to one name are made one at a time. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Role row = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        row.setRole(role);
        Role saved = roles.saveAndFlush(row);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** The roles a sheet's settings can assign; a name with none assigned is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type RoleName = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: RoleName;
}

// The roles assigned to user names on the active sheet.
@Injectable({ providedIn: 'root' })
export class Roles {
  private readonly http = inject(HttpClient);
  private readonly list = signal<RoleView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's roles from the store; null clears them. */
  load(sheetId: string | null): Observable<RoleView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RoleView[]>(this.base(sheetId)).pipe(tap((roles) => this.list.set(roles)));
  }

  /** Assign a role to a user name, replacing the one it had. */
  set(sheetId: string, user: string, role: RoleName): Observable<RoleView> {
    return this.http
      .put<RoleView>(`${this.base(sheetId)}/${encodeURIComponent(user)}`, { role })
      .pipe(
        tap((saved) =>
          this.list.update((list) =>
            [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)),
          ),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/roles`;
  }
}

